typedef unsigned short anim_flags_t;
class entity_track_tree;

class anim_base {
protected:
  unsigned short flags;
public:
  virtual void set_flag(anim_flags_t f);
  virtual void clear_flag(anim_flags_t f);
  virtual void set_flag(anim_flags_t f, bool torf);
  virtual void set_time(float t);
  virtual void frame_advance(const void *, void *);
  virtual void get_value(const void *, void *) const;
  virtual void get_value(float, void *) const;
  bool is_valid() const { return flags & 0x1000; }
  void set_valid(bool v) { set_flag(0x1000, v); }
};

class entity_anim : public anim_base {
  char data[52];
public:
  void detach();
};

template<class T> class vector {
public:
  typedef T* iterator;
  T *start;
  T *finish;
  T *end_of_storage;
  iterator begin() { return start; }
  iterator end() { return finish; }
};

typedef vector<entity_anim*> pentity_anim_vector;

class ett_manager {
public:
  void release(const entity_track_tree *ett);
};

class world_dynamics_system {
public:
  ett_manager *get_ett_manager();
};

extern world_dynamics_system *g_world_ptr;

class entity_anim_tree : public entity_anim {
  char name[4];
  const entity_track_tree *track;
  float blend_a;
  char control[36];
  pentity_anim_vector& anims;
  float floor_offset;
  const entity_track_tree *trackb;
  float blend_b;
  pentity_anim_vector anims_b;
  char control_b[36];
public:
  void deconstruct();
};

__asm__(".equ detach__11entity_anim, 0x00113A50");
__asm__(".equ get_ett_manager__21world_dynamics_system, 0x002A3770");
__asm__(".equ release__11ett_managerPC17entity_track_tree, 0x001151B0");
__asm__(".equ g_world_ptr, 0x00431A8C");

void entity_anim_tree::deconstruct()
{
  pentity_anim_vector::iterator i;
  for ( i=anims.begin(); i!=anims.end(); ++i )
  {
    entity_anim* a = *i;
    if ( a->is_valid() )
    {
      a->detach();
      a->set_valid( false );
    }
  }
  for ( i=anims_b.begin(); i!=anims_b.end(); ++i )
  {
    entity_anim* a = *i;
    if ( a->is_valid() )
    {
      a->detach();
      a->set_valid( false );
    }
  }
  set_valid( false );

  if( track )
  {
    g_world_ptr->get_ett_manager()->release( track );
    track = 0;
  }

  if( trackb )
  {
    g_world_ptr->get_ett_manager()->release( trackb );
    trackb = 0;
  }
}
